 $('#hero-search')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),d=destinations.find(v=>v.id===f.get('destination'));if(!d){$('#hero-error').textContent='Pilih tujuan terlebih dahulu.';return}filters={q:d.name,region:'',category:'',budget:'',duration:'',date:String(f.get('date')||''),sort:'popular'};save('jelajah-search',{from:f.get('from'),destination:d.id,date:f.get('date'),pax:f.get('pax')});go('/packages')});
 document.querySelectorAll('[data-wish]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const id=btn.dataset.wish;wishlist=wishlist.includes(id)?wishlist.filter(v=>v!==id):[...wishlist,id];save('jelajah-wishlist',wishlist);toast(wishlist.includes(id)?'Paket ditambahkan ke wishlist.':'Paket dihapus dari wishlist.');render()}));
 const filterIds={q:'filter-q',region:'filter-region',budget:'filter-budget',duration:'filter-duration',category:'filter-category',date:'filter-date',sort:'sort'};Object.entries(filterIds).forEach(([key,id])=>$('#'+id)?.addEventListener(key==='q'?'input':'change',e=>{filters[key]=e.target.value;if(key==='q'){clearTimeout(bind.searchTimer);bind.searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;render();const input=$('#filter-q');input?.focus();input?.setSelectionRange(pos,pos)},300)}else render()}));
