 $('#detail-book')?.addEventListener('submit',e=>{e.preventDefault();const p=packages.find(v=>route()==='/packages/'+v.slug),f=new FormData(e.currentTarget),s=p.schedules.find(v=>v.id===f.get('schedule')),n=Number(f.get('pax'));if(!s||!Number.isInteger(n)||n<1||n>s.remaining){$('#detail-error').textContent='Pilih jadwal dan jumlah peserta sesuai kuota.';return}save('jelajah-draft',{packageId:p.id,scheduleId:s.id,pax:n});go(user?'/booking/'+p.id:'/login')});
 $('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),mode=e.currentTarget.dataset.mode,email=String(f.get('email')).trim(),password=String(f.get('password'));if(!/^\S+@\S+\.\S+$/.test(email)||password.length<8){$('#auth-error').textContent='Masukkan email valid dan password minimal 8 karakter.';return}if(mode==='register'&&password!==f.get('confirm')){$('#auth-error').textContent='Konfirmasi password belum sesuai.';return}if(mode==='register'&&!String(f.get('phone')).trim()){$('#auth-error').textContent='Nomor WhatsApp wajib diisi.';return}const demo=mode==='login'?bookings.find(b=>b.contactEmail.toLowerCase()===email.toLowerCase()&&b.userId.startsWith('USR-DEMO-')):null;user={id:demo?.userId||'USR-'+email.toLowerCase(),name:mode==='register'?String(f.get('name')).trim()||'Penjelajah':demo?.customerName||email.split('@')[0],email,phone:mode==='register'?String(f.get('phone')):demo?.contactPhone||''};save('jelajah-user',user);toast('Selamat datang di Jelajah.');const draft=read('jelajah-draft',{});go(draft.packageId?'/booking/'+draft.packageId:'/my-trip')});
 $('#logout')?.addEventListener('click',()=>{user=null;localStorage.removeItem('jelajah-user');go('/')});
 $('#booking-pax')?.addEventListener('change',e=>{const n=Math.max(1,Math.min(20,Number(e.target.value)||1));const previous=[...$('#participants').querySelectorAll('input,select')].map(el=>[el.name,el.value]);$('#participants').innerHTML=participantFields(n);previous.forEach(([name,value])=>{const field=$(`[name="${name}"]`);if(field)field.value=value});$('#summary-pax').textContent=n;const p=packages.find(v=>v.id===read('jelajah-draft',{}).packageId);$('#summary-subtotal').textContent=money(p.price*n);$('#summary-total').textContent=money(p.price*n);$('#summary-discount').textContent=money(0);e.currentTarget.form.dataset.promo=''});
 $('#apply-promo')?.addEventListener('click',()=>{const code=$('#promo-code').value.trim().toUpperCase(),promo=promos.find(v=>v.code===code),draft=read('jelajah-draft',{}),p=packages.find(v=>v.id===draft.packageId),subtotal=p.price*Number($('#booking-pax').value),discount=promoDiscount(promo,subtotal);if(!discount){$('#promo-message').textContent='Kode promo tidak berlaku untuk pesanan ini.';$('#booking-form').dataset.promo='';$('#summary-discount').textContent=money(0);$('#summary-total').textContent=money(subtotal);return}$('#booking-form').dataset.promo=code;$('#promo-message').textContent=`Hemat ${money(discount)} dengan ${code}.`;$('#summary-discount').textContent=money(discount);$('#summary-total').textContent=money(subtotal-discount);toast('Promo berhasil digunakan.')});
 $('#booking-form')?.addEventListener('submit',e=>{e.preventDefault();const draft=read('jelajah-draft',{}),p=packages.find(v=>v.id===draft.packageId),s=p.schedules.find(v=>v.id===draft.scheduleId),f=new FormData(e.currentTarget),n=Number(f.get('pax'));if(!s||n<1||n>s.remaining){$('#booking-error').textContent='Jumlah peserta melebihi kuota jadwal.';return}const participants=Array.from({length:n},(_,i)=>({name:String(f.get(`participant-${i}`)||'').trim(),identityType:f.get(`identityType-${i}`),identity:String(f.get(`identity-${i}`)||'')}));if(participants.some(v=>!v.name)){$('#booking-error').textContent='Nama semua peserta wajib diisi.';return}const code=e.currentTarget.dataset.promo,promo=promos.find(v=>v.code===code),subtotal=p.price*n,discount=promoDiscount(promo,subtotal),b={id:'TRV-'+Date.now(),userId:user.id,customerName:user.name,packageId:p.id,scheduleId:s.id,departureDate:s.departureDate,participantCount:n,participants,contactPhone:String(f.get('phone')).trim(),contactEmail:String(f.get('email')).trim(),notes:String(f.get('notes')||''),subtotal,discount,total:Math.max(0,subtotal-discount),promoCode:code||'',bookingStatus:'waiting_payment',paymentStatus:'unpaid',createdAt:new Date().toISOString()};if(!b.contactPhone||!/^\S+@\S+\.\S+$/.test(b.contactEmail)){$('#booking-error').textContent='Isi WhatsApp dan email yang valid.';return}s.remaining-=n;bookings.push(b);save('jelajah-bookings',bookings);save('jelajah-packages',packages);localStorage.removeItem('jelajah-draft');toast('Booking berhasil dibuat.');go('/payment/'+b.id)});
 window.JelajahPayment.bind();
