 document.querySelectorAll('[data-voucher]').forEach(btn=>btn.addEventListener('click',()=>{const b=bookings.find(v=>v.id===btn.dataset.voucher),p=packages.find(v=>v.id===b.packageId);const blob=new Blob([`JELAJAH E-VOUCHER\nBooking: ${b.id}\nPaket: ${p.name}\nBerangkat: ${date(b.departureDate)}\nPeserta: ${b.participantCount}\nStatus: ${b.bookingStatus}\nTotal: ${money(b.total)}`],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`Jelajah-${b.id}.txt`;a.click();URL.revokeObjectURL(a.href)}));
 document.querySelectorAll('[data-review]').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.trip-card');if(card.querySelector('.review-form'))return;card.insertAdjacentHTML('beforeend',`<form class="review-form" data-booking="${btn.dataset.review}"><h3>Bagaimana perjalananmu?</h3><label>Rating<select name="rating" required><option value="5">5 — Luar biasa</option><option value="4">4 — Menyenangkan</option><option value="3">3 — Cukup</option><option value="2">2 — Kurang</option><option value="1">1 — Mengecewakan</option></select></label><label>Ulasan<textarea name="comment" rows="4" required placeholder="Ceritakan pengalamanmu"></textarea></label><label>Foto <small>opsional</small><input name="photo" type="file" accept="image/jpeg,image/png"></label><button class="button">Kirim ulasan ↗</button></form>`);card.querySelector('.review-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=bookings.find(v=>v.id===e.currentTarget.dataset.booking);reviews.push({id:'REV-'+Date.now(),bookingId:b.id,packageId:b.packageId,name:user.name,rating:Number(f.get('rating')),comment:String(f.get('comment')).trim(),images:[],createdAt:new Date().toISOString().slice(0,10)});save('jelajah-reviews',reviews);toast('Terima kasih atas ulasanmu.');render()})}));
 bindAdmin();
