 $('#promo-editor')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),code=String(f.get('code')).trim().toUpperCase(),startDate=String(f.get('startDate')),endDate=String(f.get('endDate'));if(promos.some(p=>p.code===code)||endDate<startDate){$('#promo-admin-error').textContent='Kode sudah ada atau periode tidak valid.';return}promos.push({code,type:String(f.get('type')),value:Number(f.get('value')),minPurchase:Number(f.get('minPurchase')),maxDiscount:Number(f.get('maxDiscount')),startDate,endDate,active:true});save('jelajah-promos',promos);toast('Promo berhasil disimpan.');render()});
 const refreshBooking=()=>{const q=($('#admin-search')?.value||'').toLowerCase(),status=$('#admin-booking-status')?.value,payment=$('#admin-payment-status')?.value,travel=$('#admin-travel-date')?.value;$('#admin-booking-results').innerHTML=adminBookingTable(bookings.filter(b=>(!q||`${b.id} ${b.customerName}`.toLowerCase().includes(q))&&(!status||b.bookingStatus===status)&&(!payment||b.paymentStatus===payment)&&(!travel||b.departureDate===travel)).reverse())};['admin-search','admin-booking-status','admin-payment-status','admin-travel-date'].forEach(id=>$('#'+id)?.addEventListener('input',refreshBooking));
 document.querySelectorAll('[data-proof]').forEach(btn=>btn.addEventListener('click',async()=>{const b=bookings.find(v=>v.id===btn.dataset.proof);try{const file=await loadProof(b.id);if(!file){toast('Bukti contoh tidak tersedia sebagai berkas.');return}const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=b.proofName;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{toast('Bukti belum dapat dibuka di browser ini.')}}));
 document.querySelectorAll('[data-verify]').forEach(btn=>btn.addEventListener('click',()=>{const b=bookings.find(v=>v.id===btn.dataset.verify);b.paymentStatus='paid';b.bookingStatus='confirmed';b.verifiedAt=new Date().toISOString();save('jelajah-bookings',bookings);toast('Pembayaran diverifikasi.');render()}));
 document.querySelectorAll('[data-reject]').forEach(btn=>btn.addEventListener('click',()=>{const reason=prompt('Alasan penolakan bukti pembayaran:');if(!reason?.trim())return;const b=bookings.find(v=>v.id===btn.dataset.reject);b.paymentStatus='rejected';b.bookingStatus='waiting_payment';b.paymentDeadline=new Date(Date.now()+86400000).toISOString();b.rejectionReason=reason.trim();save('jelajah-bookings',bookings);toast('Bukti pembayaran ditolak.');render()}));
