 document.querySelectorAll('[data-cancel]').forEach(btn=>btn.addEventListener('click',()=>{if(!confirm('Batalkan booking ini?'))return;const b=bookings.find(v=>v.id===btn.dataset.cancel);b.bookingStatus='cancelled';const p=packages.find(v=>v.id===b.packageId),s=p?.schedules.find(v=>v.id===b.scheduleId);if(s)s.remaining+=b.participantCount;save('jelajah-bookings',bookings);save('jelajah-packages',packages);render()}));
 document.querySelectorAll('[data-publish]').forEach(btn=>btn.addEventListener('click',()=>{const p=packages.find(v=>v.id===btn.dataset.publish);p.published=!p.published;save('jelajah-packages',packages);render()}));
