 $('#package-editor')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),existing=packages.find(v=>v.id===e.currentTarget.dataset.id),name=String(f.get('name')).trim(),slug=name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!name||!slug){$('#editor-error').textContent='Nama paket wajib diisi.';return}const schedules=[...document.querySelectorAll('#schedule-list .editor-row')].map((row,i)=>({id:row.dataset.id||`SCH-${Date.now()}-${i}`,departureDate:row.querySelector('.sch-date').value,capacity:Number(row.querySelector('.sch-capacity').value),remaining:Number(row.querySelector('.sch-remaining').value),active:row.querySelector('.sch-active').checked}));if(schedules.some(s=>!s.departureDate||s.remaining>s.capacity)){$('#editor-error').textContent='Periksa tanggal dan kuota jadwal.';return}const days=[...document.querySelectorAll('#itinerary-list .day-row')].map(row=>({day:Number(row.querySelector('.day-number').value),title:row.querySelector('.day-title').value,activities:row.querySelector('.day-activities').value.split('\n').map(v=>v.trim()).filter(Boolean)}));const lines=k=>String(f.get(k)||'').split('\n').map(v=>v.trim()).filter(Boolean),image=String(f.get('image'));const data={...(existing||seedPackages[0]),id:existing?.id||`PKG-${Date.now().toString().slice(-6)}`,slug,name,destinationId:String(f.get('destinationId')),locationLabel:String(f.get('locationLabel')),categories:[String(f.get('category'))],price:Number(f.get('price')),durationDays:Number(f.get('durationDays')),durationNights:Number(f.get('durationNights')),description:String(f.get('description')),images:[image,existing?.images[1]||image,existing?.images[2]||image],hotel:{name:String(f.get('hotel')),rating:4,location:String(f.get('locationLabel')),image:existing?.hotel.image||image},transport:{type:String(f.get('transport')),description:'Transportasi lokal sesuai itinerary.',meetingPoint:'Bandara tujuan'},includes:lines('includes'),excludes:lines('excludes'),cancellationPolicy:lines('policy'),terms:String(f.get('terms')),schedules,itinerary:days,published:f.has('published')};if(existing)Object.assign(existing,data);else packages.push(data);save('jelajah-packages',packages);toast('Data paket berhasil disimpan.');go('/admin/packages')});
